            'sections' => [
                ['id' => 'responsable', 'title' => 'Responsable du traitement', 'paragraphs' => ['La société HOME CONFORT, SAS établie en France et identifiée ci-dessous, est responsable des traitements effectués pour son site. Les demandes relatives aux données personnelles peuvent être adressées par e-mail aux coordonnées indiquées ci-dessous ou par courrier au siège.'], 'company_details' => true],
                ['id' => 'donnees', 'title' => 'Données recueillies dans la boutique', 'paragraphs' => ['Le catalogue peut être consulté sans compte. Pour préparer votre devis et votre dossier, le site recueille votre nom, votre e-mail, l’adresse, le code postal, la ville et le pays de livraison, les articles/options/quantités, le total et votre choix de paiement. Le téléphone est facultatif et sert au suivi de votre demande ou à l’organisation de la livraison. Les champs exigés sont indiqués dans le formulaire ; sans ces informations, le dossier ne peut pas être enregistré.', 'L’acceptation des CGV et la prise de connaissance de cette politique sont enregistrées avec leur date et la version des textes présentés. La case relative à la confidentialité confirme que vous avez reçu cette information ; elle ne constitue pas un consentement à la publicité ou à des traitements sans rapport avec votre demande.', 'Les coordonnées des commandes, les documents commerciaux et les preuves de virement éventuelles sont chiffrés et conservés en espace privé. Le panier et l’accès à votre dossier utilisent la session. Le site ne recueille pas de numéro complet de carte.', 'Les journaux techniques peuvent contenir l’adresse IP, le navigateur, les pages et dates d’accès. Les recherches du catalogue apparaissent dans l’URL. Aucun tag Google Analytics, Ads ou publicitaire n’est installé dans la version examinée.']],
                ['id' => 'devis', 'title' => 'Devis PDF et e-mails liés à votre demande', 'paragraphs' => ['Lorsque le service d’envoi est activé et disponible, la validation de votre panier permet de préparer un devis PDF reprenant vos coordonnées, les articles sélectionnés, leurs quantités et les montants du dossier. L’e-mail utilisé est celui que vous avez fourni. Le devis et l’accusé de réception servent à répondre à votre demande ; leur réception ne confirme ni l’encaissement d’un paiement ni l’expédition des produits.', 'La préparation du devis et son envoi relèvent des mesures précontractuelles que vous demandez. Les informations nécessaires à une commande acceptée servent ensuite à son exécution. Ces échanges n’entraînent aucune inscription à une newsletter. Le statut d’envoi visible dans votre dossier indique la remise au service de messagerie lorsqu’elle est confirmée ; il ne prouve pas la réception dans votre boîte.']],
                ['id' => 'assistance', 'title' => 'Conversations privées et réponses', 'paragraphs' => ['Lorsque la messagerie HOME CONFORT est disponible, votre nom et votre question sont nécessaires pour ouvrir un dossier ; votre e-mail est facultatif. Les coordonnées et messages sont chiffrés en base et accessibles au personnel habilité ainsi qu’au client muni de sa session ou de sa référence et de son code privé. Ces données servent à traiter la demande, selon son objet précontractuel ou contractuel ; elles ne vous inscrivent pas à une campagne.', 'Les réponses se lisent dans votre dossier privé. Les messages sont conservés pour traiter votre demande et les éventuelles réclamations.']],
                ['id' => 'mesure-interne', 'title' => 'Compteurs internes de navigation', 'paragraphs' => ['Lorsque cette fonction est activée, le site compte par jour les consultations de pages, de produits et du panier, ainsi que les ajouts au panier et ouvertures de commande. Ces agrégats ne conservent ni adresse IP, ni identifiant de visiteur, ni paramètres d’URL, ni navigateur ; ils ne permettent pas de reconstituer un parcours individuel. Aucun cookie de mesure supplémentaire ni export vers une régie publicitaire n’est ajouté. Les journaux techniques restent distincts.', 'Le dashboard présente séparément les événements nécessaires à la gestion des commandes, paiements, messages et retours. Configurer un compte Google ou Meta pour consulter ses rapports ne publie pas de balise dans la boutique. Les conditions et durées de toute mesure future devront être vérifiées avant son activation.']],
                ['id' => 'retractation', 'title' => 'Déclarations de rétractation', 'paragraphs' => []],
                ['id' => 'adresse', 'title' => 'Suggestions d’adresse', 'paragraphs' => ['Pour une adresse de livraison en France, les suggestions automatiques transmettent uniquement le texte saisi dans le champ adresse au service IGN afin de proposer une rue, un code postal et une ville. Le nom et l’e-mail ne sont pas transmis par cette recherche. Vous pouvez désactiver les suggestions, utiliser le bouton de recherche ou saisir les informations manuellement. Le site ne conserve pas un historique de ces recherches.']],
                ['id' => 'finalites', 'title' => 'Utilisation des données et conservation', 'paragraphs' => ['La préparation du devis, la gestion des commandes, leur suivi, les retours et le rapprochement d’un paiement relèvent de l’exécution du contrat ou des mesures précontractuelles demandées. Les obligations comptables et fiscales applicables reposent sur les obligations légales. La protection du service et la prévention des accès non autorisés relèvent de l’intérêt légitime de HOME CONFORT, sous réserve des droits des personnes.', 'Les données des devis, commandes, messages, retours et justificatifs sont conservées pour traiter le dossier, puis selon les obligations et délais de prescription applicables. Les durées précises ou leurs critères par traitement, ainsi que l’organisation de la suppression et des sauvegardes, doivent encore être documentés avant publication commerciale. L’expiration d’une réservation après 72 heures ne supprime pas automatiquement le dossier client.', 'Aucune inscription marketing, campagne ou compte client n’est activé par cette politique. Un futur marketing fondé sur le consentement exigera un choix distinct, facultatif et retirable ; accepter les CGV ou prendre connaissance de cette politique ne vaut pas consentement publicitaire.']],
                ['id' => 'destinataires', 'title' => 'Destinataires et services externes', 'paragraphs' => ['Les données sont destinées aux personnes habilitées chez HOME CONFORT pour traiter les devis, les commandes, les livraisons, les retours et les demandes d’assistance.', 'Lorsque l’envoi automatique du devis est activé, l’adresse e-mail, le contenu du message et le document PDF contenant les coordonnées et les articles sélectionnés sont transmis au service de messagerie Hostinger configuré par HOME CONFORT afin de remettre le devis au client. Les données nécessaires au paiement et à la livraison peuvent être communiquées aux intervenants chargés de ces opérations. Les lieux de traitement de la messagerie Hostinger et des autres services, ainsi que l’identité contractuelle des prestataires, doivent être précisés avant publication commerciale.', 'La recherche d’adresse utilise IGN selon la section dédiée. Les liens WhatsApp ouvrent votre application de messagerie ; vous rédigez et envoyez vous-même le message.', 'Les éventuels transferts hors de l’Espace économique européen et leurs garanties devront être indiqués pour chaque prestataire retenu ; aucun transfert futur n’est réputé validé par cette politique.']],
                ['id' => 'droits', 'title' => 'Vos droits', 'paragraphs' => ['Selon le traitement et sa base juridique, le RGPD prévoit des droits d’accès, de rectification, d’effacement, de limitation, d’opposition et de portabilité. Un consentement peut être retiré sans remettre en cause les traitements licites antérieurs. Certains droits connaissent des limites, notamment les obligations de conservation légales.', 'Pour exercer vos droits, écrivez à HOME CONFORT par e-mail aux coordonnées publiées sur la page Contact ou par courrier au siège, en précisant votre demande. Une réponse doit être apportée au plus tard un mois après réception. Ce délai peut être prolongé de deux mois en raison de la complexité ou du nombre de demandes ; vous devez alors être informé du prolongement et de ses motifs dans le premier mois. Si votre identité suscite un doute raisonnable, seules les informations nécessaires à sa confirmation peuvent être demandées.', 'Vous pouvez déposer une réclamation auprès de la CNIL ou d’une autorité compétente de votre lieu de résidence.'], 'return_details' => true],
                ['id' => 'france', 'title' => 'France', 'paragraphs' => ['La CNIL est l’autorité française de protection des données. L’information des personnes et les choix relatifs aux traceurs doivent être adaptés aux traitements effectivement réalisés.']],
                ['id' => 'belgique', 'title' => 'Belgique', 'paragraphs' => ['L’Autorité de protection des données est l’autorité belge. Le RGPD s’applique également aux données des utilisateurs belges ; les règles locales sur les cookies doivent être prises en compte.']],
                ['id' => 'allemagne', 'title' => 'Allemagne', 'paragraphs' => ['L’autorité de contrôle allemande compétente dépend notamment du Land et de l’organisme concerné. Elle ne sera pas attribuée à HOME CONFORT sans connaître son établissement. Le TDDDG encadre en outre le stockage et l’accès aux informations du terminal.']],
                ['id' => 'messageries', 'title' => 'WhatsApp et SMS', 'paragraphs' => ['Les liens e-mail, le numéro HOME CONFORT et les liens WhatsApp ou SMS ouvrent l’application associée à votre initiative ; le numéro HOME CONFORT ouvre WhatsApp. Le site ne transmet pas le contenu de votre message et n’envoie aucun message en votre nom. Lorsque vous ouvrez WhatsApp, Meta traite les données selon ses propres conditions et sa politique de confidentialité.']],
            ],
